import React, { useState, useEffect } from 'react';
import './App.css';
import Calendar from './components/Calendar';
import TodoForm from './components/TodoForm';
import TodoList from './components/TodoList';
import Stats from './components/Stats';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:5000/api';

function App() {
  const [todos, setTodos] = useState([]);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [activeView, setActiveView] = useState('calendar'); // calendar or list
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Fetch todos on component mount
  useEffect(() => {
    fetchTodos();
  }, []);

  const fetchTodos = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${API_BASE_URL}/todos`);
      setTodos(response.data);
      setError(null);
    } catch (err) {
      setError('Failed to fetch todos');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDateSelect = async (date) => {
    setSelectedDate(date);
    // Keep all todos loaded, just update selected date for filtering display
  };

  const handleAddTodo = async (todoData) => {
    try {
      const response = await axios.post(`${API_BASE_URL}/todos`, {
        ...todoData,
        date: selectedDate.toISOString().split('T')[0]
      });
      setTodos([...todos, response.data]);
      setError(null);
    } catch (err) {
      setError('Failed to add todo');
      console.error(err);
    }
  };

  const handleUpdateTodo = async (todoId, updatedData) => {
    try {
      const response = await axios.put(`${API_BASE_URL}/todos/${todoId}`, updatedData);
      setTodos(todos.map(t => t.id === todoId ? response.data : t));
      setError(null);
    } catch (err) {
      setError('Failed to update todo');
      console.error(err);
    }
  };

  const handleDeleteTodo = async (todoId) => {
    try {
      await axios.delete(`${API_BASE_URL}/todos/${todoId}`);
      setTodos(todos.filter(t => t.id !== todoId));
      setError(null);
    } catch (err) {
      setError('Failed to delete todo');
      console.error(err);
    }
  };

  const handleToggleTodo = async (todoId) => {
    try {
      const response = await axios.patch(`${API_BASE_URL}/todos/${todoId}/toggle`);
      setTodos(todos.map(t => t.id === todoId ? response.data : t));
      setError(null);
    } catch (err) {
      setError('Failed to toggle todo');
      console.error(err);
    }
  };



  const todosForSelectedDate = todos.filter(todo => {
    const todoDate = new Date(todo.date).toDateString();
    const selectedDateStr = selectedDate.toDateString();
    return todoDate === selectedDateStr;
  });

  return (
    <div className="app">
      <header className="app-header">
        <h1>📅 TodoList Calendar</h1>
        <p>Organize your tasks with style</p>
      </header>

      {error && (
        <div className="error-message">
          ⚠️ {error}
        </div>
      )}

      <div className="app-container">
        <div className="left-panel">
          <div className="view-toggle">
            <button
              className={`toggle-btn ${activeView === 'calendar' ? 'active' : ''}`}
              onClick={() => setActiveView('calendar')}
            >
              📆 Calendar
            </button>
            <button
              className={`toggle-btn ${activeView === 'list' ? 'active' : ''}`}
              onClick={() => setActiveView('list')}
            >
              📋 List
            </button>
          </div>

          {activeView === 'calendar' && (
            <Calendar
              selectedDate={selectedDate}
              onDateSelect={handleDateSelect}
              todos={todos}
            />
          )}

          <Stats todos={todos} />
        </div>

        <div className="right-panel">
          <div className="selected-date-info">
            <h2>{selectedDate.toLocaleDateString('en-US', { 
              weekday: 'long', 
              year: 'numeric', 
              month: 'long', 
              day: 'numeric' 
            })}</h2>
            <p>{todosForSelectedDate.length} todo(s)</p>
          </div>

          <TodoForm onAddTodo={handleAddTodo} />

          {loading ? (
            <div className="loading">Loading todos...</div>
          ) : (
            <TodoList
              todos={todosForSelectedDate}
              onUpdateTodo={handleUpdateTodo}
              onDeleteTodo={handleDeleteTodo}
              onToggleTodo={handleToggleTodo}
            />
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
